export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-otd-0001", "section": "service", "who": "reader", "text": "ВО ВТОРНИК ШЕСТОЙ НЕДЕЛИ ПО ПАСЦЕ, ВЕЧЕРА."},
  {"id": "cu-otd-0002", "section": "service", "who": "rubric", "text": "По 9-м часе творит священник начало с кадилом и со свещею, царским дверем отверзенным, и поет:"},
  {"id": "cu-otd-0003", "section": "service", "who": "priest", "text": "Христос воскресе:"},
  {"id": "cu-otd-0004", "section": "service", "who": "rubric", "text": "со стихи. И по стисех псалом:"},
  {"id": "cu-otd-0005", "section": "service", "who": "priest", "text": "Благослови душе моя Господа:"},
  {"id": "cu-otd-0006", "section": "service", "who": "rubric", "text": "И ектениа. Таже кафисма обычная."},
  {"id": "cu-otd-0007", "section": "service", "who": "priest", "text": "На Господи воззвах: поем стихиры самогласны слепаго, на 6. Глас 2:"},
  {"id": "cu-otd-0008", "section": "service", "who": "priest", "text": "Слепый родивыйся, в своем помысле глаголаше: / еда аз грех ради родительных родихся без очию, / еда аз за неверие языков родихся во обличение? / Не домышляюся вопрошати, / когда нощь, когда день? / Не терпита ми нозе каменнаго претыкания, / не видех бо солнца сияюща, / ниже во образе мене Создавшаго. / Но молю Ти ся Христе Боже, / призри на мя и помилуй мя."},
  {"id": "cu-otd-0009", "section": "service", "who": "priest", "text": "Мимоходя Иисус от святилища, / обрете человека слепа от рождения, / и умилосердився положи брение на очию его, и рече к нему: / иди умыйся в Силоаме, / и умывся прозре, славу возсылая Богу. / Соседи же его глаголаху ему: / кто твои зеницы отверзе, / ихже никтоже от зрящих исцелити возможе? / Он же возопив, рече: / Человек Иисус глаголемый, / Он ми рече, умыйся в Силоаме, и прозрех. / Той есть воистинну, / Егоже рече Моисей в законе, Христа Мессию: / Той есть Спас душ наших. Глас 4:"},
  {"id": "cu-otd-0010", "section": "service", "who": "priest", "text": "Все житие слепый нощь помышляя, / возопи к Тебе: / Господи, отверзи ми зеницы, / Сыне Давидов Спасе наш, / да со всеми и аз воспою Твою силу. Глас 5:"},
  {"id": "cu-otd-0011", "section": "service", "who": "priest", "text": "Господи, мимоходя путем, / обрел еси человека слепа от рождения, / и удивлени бывше ученицы, вопрошаху Тя глаголюще: / Учителю, кто согреши: сей ли, / или родители его, да слеп родися? / Ты же Спасе мой возопил еси к ним: / ни сей согреши, ни родители его, / но да явятся дела Божия на нем. / Мне подобает делати дела Пославшаго Мя, / яже никтоже может делати. / И сия рек, плюнув долу, и брение сотворь, / помазал еси очи его, рек к нему: / иди, умыйся в Силоамстей купели. / Он же умывся здрав бысть, и вопияше к Тебе: / верую Господи, и поклонися Тебе. / Темже вопием и мы, помилуй нас. Глас 8:"},
  {"id": "cu-otd-0012", "section": "service", "who": "priest", "text": "Правды солнце мысленное Христе Боже, / из утробы света лишеннаго, / Твоим пречистым прикосновением просветившее обоюду, / и наша очи душевныя озарившее, / сыны дне покажи, / да верою вопием Ти: / многое Твое и неизреченное, еже на нас благоутробие, / Человеколюбче, слава Тебе."},
  {"id": "cu-otd-0013", "section": "service", "who": "priest", "text": "За милосердие милости воплотивыйся, Христе Боже, / света лишеннаго от утробы, / милосердием неизреченных щедрот, / сияния Божественнаго сподобил еси, / сего зеницам перстию / создательными персты Твоими прикоснувыйся: / Сам и ныне, Светодателю, / и наша озари душевная чувства, / яко един независтнодатель."},
  {"id": "cu-otd-0014", "section": "service", "who": "priest", "text": "Слава, и ныне, глас 8: Кто возглаголет силы Твоя, Христе; / или кто изочтет чудес Твоих множества? / Сугуб бо яко виден был еси на земли за благость, / сугубы и цельбы недугующим подавал еси: / не точию бо телесныя очи отверзл еси, / иже от утробы слепому, / но и душевныя. / Темже Бога Тя исповедаше таящагося, / и всем подающа велию милость. Прокимен дне."},
  {"id": "cu-otd-0015", "section": "service", "who": "priest", "text": "На стиховне стихира, глас 5: Тебе воплощеннаго Спаса Христа, / и небес не разлучившася, / во гласех пений величаем, / яко крест и смерть приял еси за род наш, / яко человеколюбец Господь, / испровергий адова врата, / тридневно воскресл еси, / спасая души наша."},
  {"id": "cu-otd-0016", "section": "service", "who": "priest", "text": "Таже стихиры Пасхи с припевы их. Глас 5: Стих:"},
  {"id": "cu-otd-0017", "section": "service", "who": "priest", "text": "Да воскреснет Бог, / и расточатся врази Его."},
  {"id": "cu-otd-0018", "section": "service", "who": "priest", "text": "Пасха / священная нам днесь показася; / Пасха нова святая; / Пасха таинственная; / Пасха всечестная. / Пасха Христос Избавитель; / Пасха непорочная; / Пасха великая; / Пасха верных. / Пасха двери райския нам отверзающая. / Пасха всех освящающая верных. Стих:"},
  {"id": "cu-otd-0019", "section": "service", "who": "priest", "text": "Яко исчезает дым, / да исчезнут."},
  {"id": "cu-otd-0020", "section": "service", "who": "priest", "text": "Приидите / от видения жены благовестницы, / и Сиону рцыте: / приими / от нас радости благовещения, Воскресения Христова: / красуйся, ликуй / и радуйся, Иерусалиме, / Царя Христа узрев из гроба, / яко жениха происходяща. Стих:"},
  {"id": "cu-otd-0021", "section": "service", "who": "priest", "text": "Тако да погибнут грешницы от Лица Божия, / а праведницы да возвеселятся."},
  {"id": "cu-otd-0022", "section": "service", "who": "priest", "text": "Мироносицы жены, / утру глубоку, / представша гробу Живодавца, / обретоша Ангела / на камени седяща, / и той провещав им, / сице глаголаше: / что ищете Живаго с мертвыми; / что плачете Нетленнаго во тли? / Шедше, проповедите учеником Его. Стих:"},
  {"id": "cu-otd-0023", "section": "service", "who": "priest", "text": "Сей день, егоже сотвори Господь, / возрадуемся и возвеселимся в онь."},
  {"id": "cu-otd-0024", "section": "service", "who": "priest", "text": "Пасха красная, / Пасха, Господня Пасха! / Пасха всечестная / нам возсия. Пасха, / радостию друг друга обымем. / О Пасха! / Избавление скорби, / ибо из гроба днесь, / яко от чертога / возсияв Христос, / жены радости исполни, глаголя: / проповедите апостолом."},
  {"id": "cu-otd-0025", "section": "service", "who": "priest", "text": "Слава, и ныне, глас 5: Воскресения день, / и просветимся торжеством, / и друг друга обымем. / Рцем братие, / и ненавидящим нас, / простим вся Воскресением, / и тако возопиим: / Христос воскресе из мертвых, / смертию смерть поправ, / и сущим во гробех живот даровав. единожды. Таже,"},
  {"id": "cu-otd-0026", "section": "service", "who": "priest", "text": "Ныне отпущаеши:"},
  {"id": "cu-otd-0027", "section": "service", "who": "rubric", "text": "Трисвятое. И по"},
  {"id": "cu-otd-0028", "section": "service", "who": "priest", "text": "Отче наш:"},
  {"id": "cu-otd-0029", "section": "service", "who": "priest", "text": "Таже тропарь воскресен, глас 5:"},
  {"id": "cu-otd-0030", "section": "service", "who": "priest", "text": "Собезначальное Слово Отцу и Духови, / от Девы рождшееся на Спасение наше, / воспоим, вернии, и поклонимся; / яко благоволи Плотию взыти на Крест, / и смерть претерпети, / и воскресити умершия / славным воскресением Своим."},
  {"id": "cu-otd-0031", "section": "service", "who": "priest", "text": "Слава, и ныне, Богородичен: Радуйся, Двере Господня непроходимая; / радуйся, стено и покрове притекающим к Тебе. / Радуйся, необуреваемое пристанище и неискусобрачная, / рождшая плотию Творца Твоего и Бога. / Молящи не оскудевай о воспевающих / и кланяющихся рождеству Твоему. И ектениа:"},
  {"id": "cu-otd-0032", "section": "service", "who": "priest", "text": "Помилуй нас Боже:"},
  {"id": "cu-otd-0033", "section": "service", "who": "rubric", "text": "И обычный отпуст глаголет иерей без креста:"},
  {"id": "cu-otd-0034", "section": "service", "who": "priest", "text": "Воскресый из мертвых:"},
  {"id": "cu-otd-0035", "section": "service", "who": "rubric", "text": "И святаго дне поминает. И многолетны."},
  {"id": "cu-otd-0036", "section": "service", "who": "rubric", "text": "На повечерии по Достойно: и по трисвятом, кондак слепаго: Слава, и ныне: Пасхи: Аще и во гроб: Полунощницу же поем по обычаю с кафисмою. По 1-м трисвятом, вместо: Се жених грядет: глаголем тропарь воскресен: Собезначальное слово: Слава, и ныне: Богородичен его. По 2-м трисвятом, вместо: Помяни Господи яко благ: глаголем кондак Пасхи: Аще и во гроб: Посем, Господи помилуй, 12. И отпуст. Молитвы же: Помяни Господи, в надежди: не глаголем."},
  {"id": "cu-otd-0037", "section": "service", "who": "priest", "text": "В СРЕДУ 6-Я СЕДМИЦЫ ПО ПАСЦЕ, НА УТРЕНИ,"},
  {"id": "cu-otd-0038", "section": "service", "who": "rubric", "text": "Начало творит священник:"},
  {"id": "cu-otd-0039", "section": "service", "who": "priest", "text": "Слава святей, и единосущней:"},
  {"id": "cu-otd-0040", "section": "service", "who": "rubric", "text": "по обычаю, с кадилом, и со стихи, яко изобразися вечера. И по стисех глаголет настоятель, или чтец:"},
  {"id": "cu-otd-0041", "section": "service", "who": "reader", "text": "Слава в вышних Богу:"},
  {"id": "cu-otd-0042", "section": "service", "who": "rubric", "text": "И шестопсалмие по обычаю:"},
  {"id": "cu-otd-0043", "section": "service", "who": "priest", "text": "На Бог Господь: тропарь воскресен, глас 5:"},
  {"id": "cu-otd-0044", "section": "service", "who": "priest", "text": "Собезначальное Слово Отцу и Духови, / от Девы рождшееся на Спасение наше, / воспоим, вернии, и поклонимся; / яко благоволи Плотию взыти на Крест, / и смерть претерпети, / и воскресити умершия / славным воскресением Своим. [Дважды.]"},
  {"id": "cu-otd-0045", "section": "service", "who": "priest", "text": "Слава, и ныне, Богородичен: Радуйся, Двере Господня непроходимая; / радуйся, стено и покрове притекающим к Тебе. / Радуйся, необуреваемое пристанище и неискусобрачная, / рождшая плотию Творца Твоего и Бога. / Молящи не оскудевай о воспевающих / и кланяющихся рождеству Твоему."},
  {"id": "cu-otd-0046", "section": "service", "who": "priest", "text": "По 1-м стихословии, седален воскресен, глас 5:"},
  {"id": "cu-otd-0047", "section": "service", "who": "priest", "text": "Крест Господень похвалим, / погребение Святое песньми почтим, / и Воскресение Его препрославим, / яко совозстави мертвыя от гроб, яко Бог, / пленив смерти державу, и крепость диаволю, / и сущим во аде свет возсия. Стих:"},
  {"id": "cu-otd-0048", "section": "service", "who": "priest", "text": "Воскресни Господи Боже мой, да вознесется рука Твоя, / не забуди убогих Твоих до конца."},
  {"id": "cu-otd-0049", "section": "service", "who": "priest", "text": "Господи мертв нареклся еси, умертвивый смерть, / во гробе положился еси, истощивый гробы: / горе воини гроба стрежаху, / доле от века мертвыя воскресил еси. / Всесильне и Непостижиме Господи, слава Тебе."},
  {"id": "cu-otd-0050", "section": "service", "who": "priest", "text": "Слава, и ныне, Богородичен: Радуйся, Святая Горо и Богопроходная, / радуйся, одушевленная купино и неопалимая. / Радуйся, Едина к Богу мiрови Мосте, / преводяй смертныя к Вечному Животу. / Радуйся, Нетленная Отроковице, / неискусомужно рождшая Спасение душ наших."},
  {"id": "cu-otd-0051", "section": "service", "who": "rubric", "text": "И чтение Иоанна."},
  {"id": "cu-otd-0052", "section": "service", "who": "priest", "text": "По 2-м стихословии седален, глас 5:"},
  {"id": "cu-otd-0053", "section": "service", "who": "priest", "text": "Отцу и Духови собезначальный, / иже светом яко ризою одеваяйся, / человеколюбно в наше естество облечеся, / и недуги человеческия отгоняя яко Бог, / просвети и зеницы от ложесн матерних лишеннаго света. [Дважды.]"},
  {"id": "cu-otd-0054", "section": "service", "who": "priest", "text": "Воскресение Христово: Псалом 50-й."},
  {"id": "cu-otd-0055", "section": "service", "who": "rubric", "text": "Каноны три: Пасце со ирмосы на 6, и слепаго на 4, и предпразднству Вознесения, на 4."},
  {"id": "cu-otd-0056", "section": "service", "who": "priest", "text": "Канон Пасхи. Глас 1. Песнь 1. Ирмос:"},
  {"id": "cu-otd-0057", "section": "service", "who": "priest", "text": "Воскресения день, / просветимся, людие. / Пасха, Господня Пасха: / от смерти бо к жизни, / и от земли к небеси, / Христос Бог нас преведе, / победную поющия. Припев:"},
  {"id": "cu-otd-0058", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0059", "section": "service", "who": "priest", "text": "Очистим чувствия, и узрим / неприступным светом / Воскресения, Христа / блистающася, / и радуйтеся, рекуща, / ясно да услышим, / победную поюще. Припев:"},
  {"id": "cu-otd-0060", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0061", "section": "service", "who": "priest", "text": "Небеса убо достойно да веселятся, / земля же да радуется, / да празднует же мир, / видимый же весь и невидимый: / Христос бо воста, / веселие вечное."},
  {"id": "cu-otd-0062", "section": "service", "who": "priest", "text": "Иный канон Богородичен, подобен. Егоже краестрочие на первых тропарех: Феофанус. Глас тойже. Припев:"},
  {"id": "cu-otd-0063", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0064", "section": "service", "who": "priest", "text": "Умерщвления предел сломила еси, / вечную жизнь рождшая Христа, / из гроба возсиявшаго днесь, / Дево Всенепорочная, / и мир просветившаго. Припев:"},
  {"id": "cu-otd-0065", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0066", "section": "service", "who": "priest", "text": "Воскресшаго видевши Сына Твоего и Бога, / радуйся со апостолы Богоблагодатная Чистая: / и еже радуйся первее, / яко всех радости вина, восприяла еси, / Богомати Всенепорочная."},
  {"id": "cu-otd-0067", "section": "service", "who": "priest", "text": "Канон слепаго, глас 5. Песнь 1. Ирмос:"},
  {"id": "cu-otd-0068", "section": "service", "who": "priest", "text": "Землю, на нюже не возсия, ни виде солнце когда, / бездну, юже не виде нагу, широта небесная, / Израиль пройде невлажно, Господи, / и ввел еси его в гору святыни Твоея, / хваляща и поюща победную песнь."},
  {"id": "cu-otd-0069", "section": "service", "who": "priest", "text": "Распятие вольное восприим, Спасе, плотию, / источил еси благословение, и жизнь мирови, Владыко, / едине Всеблагословенне, и всех Содетелю. / Темже благословим Тя, поем и славим, поюще, / воспевающе победную песнь."},
  {"id": "cu-otd-0070", "section": "service", "who": "priest", "text": "В рове Тя преисподнейшем мертва бывша, Христе, / положи благообразный Иосиф, / и привали к дверем гроба камень, Долготерпеливе. / Но воскресл еси славне, и мiр совозставил еси поющий, / воспевающий победную песнь."},
  {"id": "cu-otd-0071", "section": "service", "who": "priest", "text": "Мvра что приносите со слезами вы, / глаголаше честным женам Ангел явлейся? / Христос воста: / текше рцыте боговидцем учеником, рыдающим и плачущим, / яко да взыграют и ликовствуют светло."},
  {"id": "cu-otd-0072", "section": "service", "who": "priest", "text": "Чудеса преславная сотворяя, Избавитель / исцели и слепа от рождения, / брением помазав, и рек: / иди умыйся в Силоаме, / яко да познаеши Мя Бога / по земли шествующа, плоть носяща, / за милосердие щедрот."},
  {"id": "cu-otd-0073", "section": "service", "who": "priest", "text": "Канон предпразднству Вознесения, егоже краестрочие, по алфавиту. Глас 5. Песнь 1. Ирмос:"},
  {"id": "cu-otd-0074", "section": "service", "who": "priest", "text": "Коня и всадника в море Чермное, / сокрушаяй брани / мышцею высокою, / Христос истрясе, / Израиля же спасе, / победную песнь поюща."},
  {"id": "cu-otd-0075", "section": "service", "who": "priest", "text": "Горе ко Отцу Христос восходит, / и приносит плоть, юже от нас восприят: / Того воспоим в похвалении днесь, / победную песнь поюще."},
  {"id": "cu-otd-0076", "section": "service", "who": "priest", "text": "Книги Писаний Божественных, / и проповеди премудрых богоглагольник, / конец яве прияша: / по востании бо Владыка, / восходит со славою в Небесная."},
  {"id": "cu-otd-0077", "section": "service", "who": "priest", "text": "Земля тайно ликует, / и небесная веселия исполняются о вознесении Христа, / древле разстоящаяся соединившаго благодатию, / и Евино преграждение разорившаго. Катавасия:"},
  {"id": "cu-otd-0078", "section": "service", "who": "priest", "text": "Спасителю Богу, / в мори люди немокрыми ногами наставльшему, / и фараона со всевоинством потопльшему, / Тому единому поим, / яко прославися."},
  {"id": "cu-otd-0079", "section": "service", "who": "priest", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-otd-0080", "section": "service", "who": "priest", "text": "Приидите, пиво пием новое, / не от камене неплодна чудодеемое, / но нетления источник / из гроба одождивша Христа, / в Немже утверждаемся. Припев:"},
  {"id": "cu-otd-0081", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0082", "section": "service", "who": "priest", "text": "Ныне вся исполнишася света, / небо же и земля, и преисподняя: / да празднует убо вся тварь / востание Христово, / в немже утверждается. Припев:"},
  {"id": "cu-otd-0083", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0084", "section": "service", "who": "priest", "text": "Вчера спогребохся Тебе Христе, / совостаю днесь / воскресшу Тебе, / сраспинахся Тебе вчера, / Сам мя спрослави Спасе во Царствии Твоем. Припев:"},
  {"id": "cu-otd-0085", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0086", "section": "service", "who": "priest", "text": "На нетленную жизнь прихожду днесь / благостию рождшагося из Тебе, Чистая, / и всем концем свет облиставшаго. Припев:"},
  {"id": "cu-otd-0087", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0088", "section": "service", "who": "priest", "text": "Бога, Егоже родила еси плотию, / из мертвых, якоже рече, / воставша видевши, Чистая, ликуй, / и Сего яко Бога Пречистая возвеличай. Ин. Ирмос:"},
  {"id": "cu-otd-0089", "section": "service", "who": "priest", "text": "Движимое сердце мое, Господи, / волнами житейскими, / утверди, во пристанище тихое / наставляя яко Бог."},
  {"id": "cu-otd-0090", "section": "service", "who": "priest", "text": "Колеблющихся сердца утвердил еси, / землю всю поколебав, Долготерпеливе, / честным распятием Твоим / еже претерпел еси плотию."},
  {"id": "cu-otd-0091", "section": "service", "who": "priest", "text": "В новем гробе Тебе положи, Щедре, Иосиф благообразный, / воскресл же еси из мертвых тридневен, новосотворивый нас."},
  {"id": "cu-otd-0092", "section": "service", "who": "priest", "text": "Что яко мертва ищете Господа? / Воскресе, якоже рече, / Ангел женам вещаше, / блистаяся божественным зраком."},
  {"id": "cu-otd-0093", "section": "service", "who": "priest", "text": "Слепа иногда от рождения, приступльша к Тебе / исцелил еси Всещедре, / славяща смотрение Твое и чудеса. Ин. Ирмос:"},
  {"id": "cu-otd-0094", "section": "service", "who": "priest", "text": "Водрузивый на ничесомже землю повелением Твоим, / и повесивый неодержимо тяготеющую / на недвижимем, Христе, камени заповедей Твоих, / Церковь Твою утверди, Едине Блаже и Человеколюбче."},
  {"id": "cu-otd-0095", "section": "service", "who": "priest", "text": "Связав Своею смертию Слове смерть, / из мертвых воскресл еси яве тридневен, / и к Небесным Спасе возшел еси со славою, / песнословящим безплотным Твое смотрение неизреченное."},
  {"id": "cu-otd-0096", "section": "service", "who": "priest", "text": "Пришел еси к земным Христе кроме тела, и облекся в плоть, / Крест претерпел еси, и воскрес из мертвых, / возшел еси со славою к началосветному Отцу Твоему, / умиротворивый всяческая."},
  {"id": "cu-otd-0097", "section": "service", "who": "priest", "text": "Поискав Христе на земли заблуждшее овча, / незаблудным Слове, сие счинил еси: / и вознесся к Небесем, / сел еси во славе одесную Твоего Родителя. / Слава многому благоутробию Твоему. Катавасия:"},
  {"id": "cu-otd-0098", "section": "service", "who": "priest", "text": "Силою Креста Твоего, Христе, / утверди мое помышление, / во еже пети и славити / спасительное Твое Вознесение."},
  {"id": "cu-otd-0099", "section": "service", "who": "priest", "text": "Кондак слепаго, глас 4. Подобен: Явился еси днесь:"},
  {"id": "cu-otd-0100", "section": "service", "who": "priest", "text": "Душевныма очима ослеплен, / к Тебе, Христе, прихожду, / якоже слепый от рождения, / покаянием зову Ти: / Ты сущих во тьме Свет пресветлый. Икос:"},
  {"id": "cu-otd-0101", "section": "service", "who": "priest", "text": "Струю ми даруй, Христе, премудрости неизреченныя, и разума горняго, / свете сущих во тьме, и прельщаемых наставниче, / да возмогу чудеса Твоя поведати, окаянный, / яже божественная книга научи Евангелиа мира, / сиесть, слепаго чудотворение: / яко от рождения слеп сый, / очи чувственныя приемлет и душевныя, верою взывая: / Ты сущих во тьме свет пресветлый."},
  {"id": "cu-otd-0102", "section": "service", "who": "priest", "text": "Таже седален, глас 1. Подобен: Гроб твой спасе:"},
  {"id": "cu-otd-0103", "section": "service", "who": "priest", "text": "Воочил еси Христе от утробы рожденнаго без очес, / показавый Иудеем Спасе мой, славу Твою неизреченную, / и яко свет всех еси, / но завистию Тя ослепленнии умом наветующе, / живота Подателя умертвити поущахуся."},
  {"id": "cu-otd-0104", "section": "service", "who": "priest", "text": "Слава, и ныне. Подобен: Родился еси, яко Ты Спасе мой восхотевый, / явился же паки еси, яко Ты восхотел еси, / и пострадал еси яко человек, / яко Бог же воскресл еси. / На Небеса со славою возшел еси, / и возвел еси человеческое существо, / и славою удобрил еси."},
  {"id": "cu-otd-0105", "section": "service", "who": "priest", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-otd-0106", "section": "service", "who": "priest", "text": "На Божественней стражи / богоглаголивый Аввакум / да станет с нами, и покажет / светоносна Ангела, / ясно глаголюща: / днесь спасение миру, / яко воскресе Христос, / яко всесилен. Припев:"},
  {"id": "cu-otd-0107", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0108", "section": "service", "who": "priest", "text": "Мужеский убо пол, / яко разверзый девственную утробу, / явися Христос: / яко человек же, / Агнец наречеся: / непорочен же, / яко невкусен скверны, / наша Пасха, / и яко Бог истинен / совершен речеся. Припев:"},
  {"id": "cu-otd-0109", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0110", "section": "service", "who": "priest", "text": "Яко единолетный агнец, / благословенный нам венец Христос, / волею за всех заклан бысть, / Пасха чистительная, / и паки из гроба красное / правды нам возсия Солнце. Припев:"},
  {"id": "cu-otd-0111", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0112", "section": "service", "who": "priest", "text": "Богоотец убо Давид / пред сенным ковчегом скакаше играя, / людие же Божии святии, / образов сбытие зряще, / веселимся Божественне, / яко воскресе Христос, / яко Всесилен. Припев:"},
  {"id": "cu-otd-0113", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0114", "section": "service", "who": "priest", "text": "Создавый Адама, Твоего праотца, Чистая, / зиждется от Тебе, / и смертное жилище разори Своею смертию днесь, / и озари вся / божественными блистаньми воскресения. Припев:"},
  {"id": "cu-otd-0115", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0116", "section": "service", "who": "priest", "text": "Егоже родила еси Христа, / прекрасно из мертвых возсиявша, Чистая, зрящи, / добрая и непорочная в женах и красная, / днесь во спасение всех, / со апостолы радующися, Того прославляй. Ин. Ирмос:"},
  {"id": "cu-otd-0117", "section": "service", "who": "priest", "text": "Услышах Господи слух Твой, и убояхся, / разумех смотрение Твое, и прославих Тя, / едине Человеколюбче."},
  {"id": "cu-otd-0118", "section": "service", "who": "priest", "text": "Умерша мя древом, пожрен быв, Спасе мой, / жизнь сый, оживил еси за великую милость: / сего ради, Слове, славлю Тя."},
  {"id": "cu-otd-0119", "section": "service", "who": "priest", "text": "Учеником, Господи, соводворяяся преславно, / сим глаголал еси: идите, / проповедите всюду Мое Воскресение."},
  {"id": "cu-otd-0120", "section": "service", "who": "priest", "text": "Уверяя, Господи, востание Твое, еже из гроба, / любящим Тя Христе, / во дни многи соводворился еси, радость творя им."},
  {"id": "cu-otd-0121", "section": "service", "who": "priest", "text": "Воочил еси Господи, слепа из утробы рожденна, рек: / иди, умыйся, и прозри, Мое славя Божество. Ин. Ирмос:"},
  {"id": "cu-otd-0122", "section": "service", "who": "priest", "text": "Божественное Твое разумев истощание / прозорливо, Аввакум, Христе, со трепетом вопияше Тебе: / во Спасение людей Твоих / спасти помазанныя Твоя пришел еси."},
  {"id": "cu-otd-0123", "section": "service", "who": "priest", "text": "Прежде грехом осужденное естество наше Всецарю, / Твоим приятием помиловася, / песнословящее Твое со страхом востание, и Божественное Вознесение."},
  {"id": "cu-otd-0124", "section": "service", "who": "priest", "text": "Дивятся безплотных чини, / смотряюще Тя Христе носяща тело земное, / и возшедша на облак, и к небесным восходяща."},
  {"id": "cu-otd-0125", "section": "service", "who": "priest", "text": "Слава: Видевше очервлены ризы Твоя Христе Всецарю, / Твоим восходом ужасошася ангельския силы, / и страхом, и радостию поклонишася."},
  {"id": "cu-otd-0126", "section": "service", "who": "priest", "text": "И ныне: Восплещим рукама, Господь востав из мертвых, / на Небеса взыде, повинувшимся Ему ангелом, / яко Творцу и Богу нашему. Катавасия:"},
  {"id": "cu-otd-0127", "section": "service", "who": "priest", "text": "Услышах слух силы Креста, / яко рай отверзеся им, / и возопих: / слава силе Твоей Господи."},
  {"id": "cu-otd-0128", "section": "service", "who": "priest", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-otd-0129", "section": "service", "who": "priest", "text": "Утренюем утреннюю глубоку, / и вместо мира песнь принесем Владыце, / и Христа узрим / правды Солнце, / всем жизнь возсияюща. Припев:"},
  {"id": "cu-otd-0130", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0131", "section": "service", "who": "priest", "text": "Безмерное Твое благоутробие, / адовыми узами содержимии зряще, / к свету идяху, Христе, / веселыми ногами, / Пасху хваляще вечную. Припев:"},
  {"id": "cu-otd-0132", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0133", "section": "service", "who": "priest", "text": "Приступим свещеноснии, / исходящу Христу из гроба, яко жениху, / и спразднуем любопразднственными чинми / Пасху Божию спасительную. Припев:"},
  {"id": "cu-otd-0134", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0135", "section": "service", "who": "priest", "text": "Просвещается божественными лучами и живоносными / воскресения Сына Твоего, / Богомати Пречистая, / и радости исполняется благочестивых собрание. Припев:"},
  {"id": "cu-otd-0136", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0137", "section": "service", "who": "priest", "text": "Не разверзл еси врата девства в воплощении, / гроба не разрушил еси печатей, Царю создания: / отонудуже воскресшаго Тя зрящи, Мати, радовашеся. Ин. Ирмос:"},
  {"id": "cu-otd-0138", "section": "service", "who": "priest", "text": "Окаянную душу мою, нощеборющуюся со тьмою страстей, / предварив ущедри, и возсияй мысленное солнце, / днесветлыя звезды во мне, / во еже разделити нощь от света."},
  {"id": "cu-otd-0139", "section": "service", "who": "priest", "text": "Вознеслся еси на Древо, Щедре, / и совознесл еси вся человеки, / и борителя змия умертвил еси, / и оживил еси создание рук Твоих, яко един Бог всех."},
  {"id": "cu-otd-0140", "section": "service", "who": "priest", "text": "Положился еси во гробе волею, Царю Безсмертне, / и царствия адова вся истощил еси, / мертвыя Воскресением Твоим воздвигнув."},
  {"id": "cu-otd-0141", "section": "service", "who": "priest", "text": "Чудеса велия соделовающаго, Слове, на земли, / людие убиша Тя, беззаконнии: / но Сам, Господи, един всесилен сый, якоже предрекл еси, / из мертвых воскресл еси, Христе."},
  {"id": "cu-otd-0142", "section": "service", "who": "priest", "text": "Очи отверзл невидевшаго свет чувственный, / души просветил еси зеницы, / и славити сотворил еси сего, познавша Тя, Творца, / за благоутробие явившася человека. Ин. Ирмос:"},
  {"id": "cu-otd-0143", "section": "service", "who": "priest", "text": "Одеяйся Светом, яко ризою, / к Тебе утреннюю, и Тебе зову: / душу мою просвети омраченную, Христе, / яко Един Благоутробен."},
  {"id": "cu-otd-0144", "section": "service", "who": "priest", "text": "Разрешив осуждение человечества, / Христос воскресе и вознесеся к Небесным, / Отчим соседением почет, ихже возлюби. [Дважды.]"},
  {"id": "cu-otd-0145", "section": "service", "who": "priest", "text": "Слава: По воскресении радостнотворивый Христе ученики Твоя, / возшел еси горе, к Твоему Родителю, / Егоже не разлучился еси, аще и Человеком беседовал еси."},
  {"id": "cu-otd-0146", "section": "service", "who": "priest", "text": "И ныне: Закону предсения, / и проповедания богоглаголивых исполнив, Христе / возшел еси, облаку Тя подъемшу Спасе, к небесным. Катавасия:"},
  {"id": "cu-otd-0147", "section": "service", "who": "priest", "text": "Утренююще вопием Ти / Господи, спаси ны: / Ты бо еси Бог наш, / разве бо Тебе иного не знаем."},
  {"id": "cu-otd-0148", "section": "service", "who": "priest", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-otd-0149", "section": "service", "who": "priest", "text": "Снизшел еси в преисподняя земли, / и сокрушил еси вереи вечныя, / содержащия связанныя, Христе, / и тридневен, яко от кита Иона, / воскресл еси от гроба. Припев:"},
  {"id": "cu-otd-0150", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0151", "section": "service", "who": "priest", "text": "Сохранив цела знамения Христе, / воскресл еси от гроба, / ключи Девы не вредивый в рождестве Твоем, / и отверзл еси нам райския двери. Припев:"},
  {"id": "cu-otd-0152", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0153", "section": "service", "who": "priest", "text": "Спасе мой, / живое же и нежертвенное заколение, / яко Бог Сам Себе / волею привел Отцу, / совоскресил еси всероднаго Адама, / воскрес от гроба. Припев:"},
  {"id": "cu-otd-0154", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0155", "section": "service", "who": "priest", "text": "Возведеся древле держимое смертию и тлением, / воплотившимся от Твоего пречистаго чрева, / к нетленней и присносущней жизни, / Богородице Дево. Припев:"},
  {"id": "cu-otd-0156", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0157", "section": "service", "who": "priest", "text": "Сниде в преисподняя земли, / в ложесна Твоя, Чистая, сшедый, / и вселивыйся и воплотивыйся паче ума, / и воздвиже с Собою Адама, / воскрес от гроба. Ин. Ирмос:"},
  {"id": "cu-otd-0158", "section": "service", "who": "priest", "text": "Якоже пророка от зверя избавил еси, Господи, / и мене из глубины несодержимых страстей возведи, молюся, / да приложу призрети ми ко храму святому Твоему."},
  {"id": "cu-otd-0159", "section": "service", "who": "priest", "text": "Распныйся с разбойники, Владыко, / избавил еси от разбойник лукавых, душетленных страстей, Человеколюбче Господи, / вся поющия Твое распятие и востание согласно."},
  {"id": "cu-otd-0160", "section": "service", "who": "priest", "text": "Положиша без дыхания Тебе мертва, Христе, во гробе, / всем мертвым вдыхающа жизнь: / воскресл же еси, Господи, вся истощивый, Слове, гробы, / Божественною Твоею силою."},
  {"id": "cu-otd-0161", "section": "service", "who": "priest", "text": "По востании, Христе, другом глаголал еси: / седите убо во Иерусалиме, / дондеже облечетеся силою свыше непобедимою, и известною помощию."},
  {"id": "cu-otd-0162", "section": "service", "who": "priest", "text": "Брение сотворь, очи слепаго от рождения помазал еси, / и даровал еси ему прозрети, / поющу Твою, Слове, неизреченную силу, еюже спасл еси мир. Ин. Ирмос:"},
  {"id": "cu-otd-0163", "section": "service", "who": "priest", "text": "Неистовствующееся бурею душетленною, / Владыко Христе, страстей море укроти, / и от тли возведи мя, яко Благоутробен."},
  {"id": "cu-otd-0164", "section": "service", "who": "priest", "text": "Странное видение явился еси ангелом, / человечь зрак нося, / восходом Твоим страшным Человеколюбче: / темже со страхом воспеваем Тя. [Дважды.]"},
  {"id": "cu-otd-0165", "section": "service", "who": "priest", "text": "Слава: Всех Господь со славою восходит светло / к Своему Безначальному Родителю: / вся тварь ныне празднует ликующи."},
  {"id": "cu-otd-0166", "section": "service", "who": "priest", "text": "И ныне: Всяк язык днесь да вопиет: / в воскликновении, Христос взыде, / и в трубы Божественном гласе к небесем, ихже не остави. Катавасия:"},
  {"id": "cu-otd-0167", "section": "service", "who": "priest", "text": "Обыде мя бездна, / гроб мне кит бысть, / аз же возопих к Тебе, Человеколюбцу, / и спасе мя десница Твоя, Господи."},
  {"id": "cu-otd-0168", "section": "service", "who": "priest", "text": "Кондак Пасце, глас 8: Аще и во гроб снизшел еси, Безсмертне, / но адову разрушил еси силу, / и воскресл еси, яко победитель, Христе Боже, / женам мироносицам вещавый: радуйтеся, / и Твоим апостолом мир даруяй, / падшим подаяй воскресение. Икос:"},
  {"id": "cu-otd-0169", "section": "service", "who": "priest", "text": "Еже прежде солнца Солнце зашедшее иногда во гроб, / предвариша ко утру, ищущия яко дне мvроносицы девы, / и друга ко друзей вопияху: / о другини! Приидите, вонями помажем тело живоносное и погребеное, / плоть воскресившаго падшаго Адама, лежащую во гробе. / Идем, потщимся якоже волсви, и поклонимся, / и принесем мvра яко дары, не в пеленах, но в плащанице обвитому, / и плачим, и возопиим: о Владыко, востани, / падшим подаяй воскресение."},
  {"id": "cu-otd-0170", "section": "service", "who": "rubric", "text": "Синаксарь минеи."},
  {"id": "cu-otd-0171", "section": "service", "who": "priest", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-otd-0172", "section": "service", "who": "priest", "text": "Отроки от пещи избавивый, / быв Человек, / страждет яко смертен, / и страстию смертное, / в нетления облачит благолепие, / Един благословен / отцев Бог, и препрославлен. Припев:"},
  {"id": "cu-otd-0173", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0174", "section": "service", "who": "priest", "text": "Жены с миры богомудрыя в след Тебе течаху: / Егоже, яко мертва, со слезами искаху, / поклонишася радующияся Живому Богу, / и Пасху тайную / Твоим, Христе, учеником благовестиша. Припев:"},
  {"id": "cu-otd-0175", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0176", "section": "service", "who": "priest", "text": "Смерти празднуем умерщвление, / адово разрушение, / иного жития вечнаго начало, / и играюще поем Виновнаго, / Единаго благословеннаго / отцев Бога, и препрославленнаго. Припев:"},
  {"id": "cu-otd-0177", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0178", "section": "service", "who": "priest", "text": "Яко воистинну священная, / и всепразднственная сия спасительная нощь, / и светозарная, / светоноснаго дне, / востания сущи провозвестница: / в нейже безлетный Свет из гроба плотски всем возсия. Припев:"},
  {"id": "cu-otd-0179", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0180", "section": "service", "who": "priest", "text": "Умертвив Сын Твой смерть, Всенепорочная, днесь, / всем смертным пребывающий живот / во веки веков дарова, / един благословенный / отцев Бог и препрославленный. Припев:"},
  {"id": "cu-otd-0181", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0182", "section": "service", "who": "priest", "text": "Всем царствуяй созданием, быв человек, / вселися в Твою, Богоблагодатная, утробу, / и распятие претерпев и смерть, / воскресе боголепно, / совозставив нас яко всесилен. Ин. Ирмос:"},
  {"id": "cu-otd-0183", "section": "service", "who": "priest", "text": "Огня гасилище отроков молитва, орошающая пещь, / проповедница чудесе, не опаляющи, ниже сожигающи, / песнословцы Бога отец наших."},
  {"id": "cu-otd-0184", "section": "service", "who": "priest", "text": "Воздижену Тебе на Древо, Спасе, / погасе солнце, земля волнуяшеся, колебашеся тварь вся, / и от гроб мертвии востаяху."},
  {"id": "cu-otd-0185", "section": "service", "who": "priest", "text": "Воставшу Ти из мертвых, Царю, / души совозсташа тамо спящия, / славящия силу Твою. / Еюже смертныя узы разрешишася."},
  {"id": "cu-otd-0186", "section": "service", "who": "priest", "text": "Рано миропомазати Тя женский прииде лик, / уведевше же, Господи, воставша Тя, / радовахуся со священными ученики: / имиже подаждь нам очищение зол."},
  {"id": "cu-otd-0187", "section": "service", "who": "priest", "text": "Брением помазал еси очи слепаго, / и сему повелел еси к Силоаму ити, / омывся же, прозре, / песнословя Тя, Христе, Царю всех. Ин. Ирмос:"},
  {"id": "cu-otd-0188", "section": "service", "who": "priest", "text": "Превозносимый отцев Господь / пламень угаси, отроки ороси, согласно поющия: / Боже, благословен еси."},
  {"id": "cu-otd-0189", "section": "service", "who": "priest", "text": "Растерзав средостение вражды Господи, Крестом и страстию Твоею, / облаком носимь возшел еси со славою к Безначальному Отцу."},
  {"id": "cu-otd-0190", "section": "service", "who": "priest", "text": "Трепетни взываху Силы: возьмите врата, / прииде Христос тело земное нося, / и Божественною страстию велиара умертвив."},
  {"id": "cu-otd-0191", "section": "service", "who": "priest", "text": "Слава: Что Твоя ризы червлены Человеколюбче? / Силам Божественным вопрошающим: / точило ныне изгнетох, Христос восходя вопияше."},
  {"id": "cu-otd-0192", "section": "service", "who": "priest", "text": "И ныне: Песньми Твое распятие Христе, / и востание согласно славим, / светло празднующе о вознесении честнем Твоем во веки. Катавасия:"},
  {"id": "cu-otd-0193", "section": "service", "who": "priest", "text": "В пещи огненней / песнословцы спасый отроки, / благословен Бог отец наших."},
  {"id": "cu-otd-0194", "section": "service", "who": "priest", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-otd-0195", "section": "service", "who": "priest", "text": "Сей нареченный и святый день, / Един суббот Царь и Господь, / праздников праздник / и торжество есть торжеств, / воньже благословим Христа во веки. Припев:"},
  {"id": "cu-otd-0196", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0197", "section": "service", "who": "priest", "text": "Приидите, новаго винограда рождения, / Божественнаго веселия, / в нарочитом дни Воскресения, / Царствия Христова приобщимся, / поюще Его, / яко Бога, во веки. Припев:"},
  {"id": "cu-otd-0198", "section": "service", "who": "priest", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0199", "section": "service", "who": "priest", "text": "Возведи окрест очи твои, Сионе, и виждь: / се бо приидоша к тебе, / яко богосветлая светила, / от запада, и севера, и моря, / и востока чада твоя, / в тебе благословящая Христа во веки. Припев:"},
  {"id": "cu-otd-0200", "section": "service", "who": "priest", "text": "Пресвятая Троице, Боже наш, слава Тебе. Троичен:"},
  {"id": "cu-otd-0201", "section": "service", "who": "priest", "text": "Отче Вседержителю, и Слове, и Душе, / треми соединяемое во Ипостасех Естество, / Пресущественне и Пребожественне, / в Тя крестихомся, / и Тя благословим во вся веки. Припев:"},
  {"id": "cu-otd-0202", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0203", "section": "service", "who": "priest", "text": "Прииде Тобою в мир Господь, Дево Богородице, / и чрево адово расторг, / смертным нам воскресение дарова: / Темже благословим Его во веки. Припев:"},
  {"id": "cu-otd-0204", "section": "service", "who": "priest", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0205", "section": "service", "who": "priest", "text": "Всю низложив смерти державу Сын Твой, Дево, / Своим воскресением, / яко Бог крепкий совознесе нас и обожи: / темже воспеваем Его во веки. Ин. Ирмос:"},
  {"id": "cu-otd-0206", "section": "service", "who": "priest", "text": "Ангелов сонм, человеков собор, / Царя и Зиждителя всех, / священницы пойте, благословите левити, / людие превозносите во вся веки."},
  {"id": "cu-otd-0207", "section": "service", "who": "priest", "text": "Ангельстии чинове на Кресте Тя видевше висима, Христе Всецарю, / и тварь всю изменяюща страхом, / ужасошася, поюще Твое человеколюбие."},
  {"id": "cu-otd-0208", "section": "service", "who": "priest", "text": "Ад доле Тебе видев, стеняше, / и подаваше скоро мертвыя, / от века тамо хранимыя, Христе, / песнословящия Твое человеколюбие."},
  {"id": "cu-otd-0209", "section": "service", "who": "priest", "text": "Сотворяя чудеса, Христе, изрядная, / волею воздвижен был еси на Крест, / и с мертвыми совокупился еси, умертвивый ада, / и вся мужеством отрешил еси узники."},
  {"id": "cu-otd-0210", "section": "service", "who": "priest", "text": "Слепаго воочил еси к Тебе приступивша, Христе, / сему повелевый в Силоамову купель ити, / омытися и прозрети, и Бога Тя проповедати, / плотию явившагося во спасение мiра. Ин. Ирмос:"},
  {"id": "cu-otd-0211", "section": "service", "who": "priest", "text": "Тебе, Вседетелю, / в пещи отроцы, всемирный лик сплетше, пояху: / дела всякая, Господа пойте / и превозносите во вся веки."},
  {"id": "cu-otd-0212", "section": "service", "who": "priest", "text": "Свет Тя от Света сущий, / облак светел подъят от горы масличныя, / всем зрящим Божественным учеником Твоим, / и Тебе воспевающим во вся веки."},
  {"id": "cu-otd-0213", "section": "service", "who": "priest", "text": "Руками псаломски восплещим, / воскресе Христос Бог наш, / и взыде, отонудуже сниде к нам человеколюбно, / умиротворивый древле разстоящаяся."},
  {"id": "cu-otd-0214", "section": "service", "who": "priest", "text": "Благословим Отца, и Сына, и Святаго Духа, Господа."},
  {"id": "cu-otd-0215", "section": "service", "who": "priest", "text": "Поя Давид вопиет: / Христос взыде на Херувимех Своих, / и возлете яве на крилу Умных Чинов. / Егоже превозносим во вся веки."},
  {"id": "cu-otd-0216", "section": "service", "who": "priest", "text": "И ныне: Явился еси учеником воскрес от гроба, / и сих возвел еси на гору масличную, / отонудуже облак светел подъем, / взят к горним Христе Тебе со славою."},
  {"id": "cu-otd-0217", "section": "service", "who": "priest", "text": "Хвалим, благословим, покланяемся Господеви, / поюще и превозносяще во вся веки. Катавасия:"},
  {"id": "cu-otd-0218", "section": "service", "who": "priest", "text": "Из Отца прежде век рожденнаго Сына и Бога, / и в последняя лета воплощеннаго от Девы Матере, / священницы пойте, / людие превозносите во вся веки."},
  {"id": "cu-otd-0219", "section": "service", "who": "rubric", "text": "Честнейшую: не поем, но поем припевы Пасхи."},
  {"id": "cu-otd-0220", "section": "service", "who": "priest", "text": "Припевы на 9-й песни: Величит душа моя / воскресшаго тридневно от гроба / Христа Жизнодавца. И ирмос:"},
  {"id": "cu-otd-0221", "section": "service", "who": "priest", "text": "Светися:"},
  {"id": "cu-otd-0222", "section": "service", "who": "rubric", "text": "И вторый лик поет тойже припев и ирмос."},
  {"id": "cu-otd-0223", "section": "service", "who": "rubric", "text": "Таже первый лик поет вторый припев:"},
  {"id": "cu-otd-0224", "section": "service", "who": "choir", "text": "Величит душа моя / волею страдавша, и погребена, / и воскресшаго тридневно от гроба. И ирмос:"},
  {"id": "cu-otd-0225", "section": "service", "who": "choir", "text": "Светися:"},
  {"id": "cu-otd-0226", "section": "service", "who": "rubric", "text": "И вторый лик поет тойже припев, и ирмос."},
  {"id": "cu-otd-0227", "section": "service", "who": "rubric", "text": "Таже первый лик поет третий припев:"},
  {"id": "cu-otd-0228", "section": "service", "who": "choir", "text": "Христос новая Пасха, / Жертва живая, / Агнец Божий, / вземляй грехи мира."},
  {"id": "cu-otd-0229", "section": "service", "who": "rubric", "text": "И стих. И вторый лик поет тойже припев и стих."},
  {"id": "cu-otd-0230", "section": "service", "who": "rubric", "text": "Таже первый лик поет четвертый припев:"},
  {"id": "cu-otd-0231", "section": "service", "who": "choir", "text": "Ангел вопияше Благодатней: / Чистая Дево, радуйся! / И паки реку: радуйся! / Твой Сын воскресе / тридневен от гроба, / и мертвыя воздвигнувый: / людие, веселитеся."},
  {"id": "cu-otd-0232", "section": "service", "who": "rubric", "text": "И стих. И вторый лик поет тойже припев и стих."},
  {"id": "cu-otd-0233", "section": "service", "who": "choir", "text": "И прочих осмь припевов припевают по единожды ко стихом:"},
  {"id": "cu-otd-0234", "section": "service", "who": "choir", "text": "Возбудил еси уснув мертвыя от века, / царски рыкавый яко от Иуды лев."},
  {"id": "cu-otd-0235", "section": "service", "who": "choir", "text": "Магдалина Мария притече ко гробу, / и Христа видевши, / яко вертоградаря вопрошаше."},
  {"id": "cu-otd-0236", "section": "service", "who": "choir", "text": "Ангел облистаяй женам вопияше: / престаните от слез, яко Христос воскресе."},
  {"id": "cu-otd-0237", "section": "service", "who": "choir", "text": "Христос воскресе, смерть поправый, / и мертвыя воздвигнувый, / людие веселитеся."},
  {"id": "cu-otd-0238", "section": "service", "who": "choir", "text": "Днесь всяка тварь веселится и радуется: / яко Христос воскресе, и ад пленися."},
  {"id": "cu-otd-0239", "section": "service", "who": "choir", "text": "Днесь Владыка плени ада, / воздвигнувый юзники, яже от века имяше люте одержимыя."},
  {"id": "cu-otd-0240", "section": "service", "who": "choir", "text": "Величит душа моя / Триипостаснаго и Нераздельнаго Божества державу."},
  {"id": "cu-otd-0241", "section": "service", "who": "choir", "text": "Радуйся, Дево, радуйся, / радуйся, Благословенная, / радуйся, Препрославленная! / Твой бо Сын воскресе тридневен от гроба."},
  {"id": "cu-otd-0242", "section": "service", "who": "rubric", "text": "Последи же первый лик поет паки первый припев и ирмос. Таже оба лика, сошедшеся вкупе, поют ирмос и тропарь:"},
  {"id": "cu-otd-0243", "section": "service", "who": "choir", "text": "Христос воскресе: трижды."},
  {"id": "cu-otd-0244", "section": "service", "who": "choir", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-otd-0245", "section": "service", "who": "choir", "text": "Светися, светися, / новый Иерусалиме: / слава бо Господня / на тебе возсия. / Ликуй ныне / и веселися, Сионе. / Ты же, Чистая, красуйся, Богородице, / о востании Рождества Твоего. Припев:"},
  {"id": "cu-otd-0246", "section": "service", "who": "choir", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0247", "section": "service", "who": "choir", "text": "О Божественнаго, о любезнаго, / о сладчайшаго Твоего гласа! / С нами бо неложно / обещался еси быти, / до скончания века, Христе: / Егоже, вернии, / утверждение надежди имуще, радуемся. Припев:"},
  {"id": "cu-otd-0248", "section": "service", "who": "choir", "text": "Христос воскресе из мертвых."},
  {"id": "cu-otd-0249", "section": "service", "who": "choir", "text": "О Пасха велия и священнейшая, Христе! / О мудросте, и Слове Божий, и сило! / Подавай нам истее Тебе причащатися, / в невечернем дни Царствия Твоего. Припев:"},
  {"id": "cu-otd-0250", "section": "service", "who": "choir", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0251", "section": "service", "who": "choir", "text": "Согласно, Дево, Тебе блажим вернии: / радуйся, двере Господня: / радуйся, граде одушевленный: / радуйся, Еяже ради нам ныне возсия свет, / из Тебе Рожденнаго из мертвых Воскресения. Припев:"},
  {"id": "cu-otd-0252", "section": "service", "who": "choir", "text": "Пресвятая Богородице, спаси нас."},
  {"id": "cu-otd-0253", "section": "service", "who": "choir", "text": "Веселися и радуйся божественная двере Света: / зашедый бо Иисус во гроб возсия, / просияв солнца светлее, / и верныя вся озарив, / Богорадованная Владычице. Ин. Ирмос:"},
  {"id": "cu-otd-0254", "section": "service", "who": "choir", "text": "Яко сотвори Тебе величия Сильный, / Деву явль Тя чисту по рождестве, / яко рождшую без семене Своего Творца: / тем Тя, Богородице, величаем."},
  {"id": "cu-otd-0255", "section": "service", "who": "choir", "text": "На Древе крестнем пригвоздился еси, Христе Боже, / и вся победил еси вражия сопротивная начала, / и первую клятву потребил еси, Спасе: / темже Тя по долгу величаем."},
  {"id": "cu-otd-0256", "section": "service", "who": "choir", "text": "Яко виде Тя, Слове, ад доле с душею, воздохну, / и вся мертвыя страхом отреши, / познавшия державу власти Твоея: / темже Тя по долгу величаем."},
  {"id": "cu-otd-0257", "section": "service", "who": "choir", "text": "Знамения сотворяюща, и чудеса страшная, / собор еврейский зря, завистию уби, / пленившаго ад Воскресением Своим, / и всех, яко силен, возставляющаго."},
  {"id": "cu-otd-0258", "section": "service", "who": "choir", "text": "Востал еси, якоже рекл еси, Животодавче, из мертвых, / и явился еси святым учеником по востании, / знамения сотворивый, и воочивый слепыя: / с нимиже Тя во веки величаем. Ин. Ирмос:"},
  {"id": "cu-otd-0259", "section": "service", "who": "choir", "text": "Исаие, ликуй, / Дева име во чреве / и роди Сына Еммануила, / Бога же и Человека, / Восток имя Ему, / Его же величающе, / Деву ублажаем."},
  {"id": "cu-otd-0260", "section": "service", "who": "choir", "text": "Священное торжество вся тварь приносит яве / Вознесению Твоему Слове Божий, / имже принесл еси Отцу Твоему, / еже от нас естество восприял еси паче слова неизменне."},
  {"id": "cu-otd-0261", "section": "service", "who": "choir", "text": "Яко Бог стерл еси врата адова Спасе и вереи, / и воскрес из мертвых, / к Небесным востекл еси Чином Ангельским, / врата возмите, вопиющим со удивлением."},
  {"id": "cu-otd-0262", "section": "service", "who": "choir", "text": "Твоему Божественному восходу дивящимся Божественным учеником, / предсташа явственно ангели, тем вопиюще: / Егоже видите восходяща на Небеса, / Сей приидет со славою судити всем."},
  {"id": "cu-otd-0263", "section": "service", "who": "choir", "text": "Слава: Еже Христе даровал еси мир учеником, к горним древле восходя, / той и нам богатно низпосли, в любви всех содержая, / яко да согласно Тебе Спаса величаем."},
  {"id": "cu-otd-0264", "section": "service", "who": "choir", "text": "И ныне: Светоносная колесница Солнца Мысленнаго, / Ты была еси воистинну, нескверная Чистая, / имже седящии во тьме / видеша свет познания, по долгу Тя славяще. Катавасия:"},
  {"id": "cu-otd-0265", "section": "service", "who": "choir", "text": "Тя паче ума и словесе Матерь Божию, / в лето Безлетнаго неизреченно рождшую, / вернии единомудренно величаем."},
  {"id": "cu-otd-0266", "section": "service", "who": "choir", "text": "Ексапостиларий праздника. Самогласен:"},
  {"id": "cu-otd-0267", "section": "service", "who": "choir", "text": "Плотию уснув, / яко мертв, / Царю и Господи, / тридневен воскресл еси, / Адама воздвиг от тли, / и упразднив смерть: / Пасха нетления, / мира спасение. Дважды."},
  {"id": "cu-otd-0268", "section": "service", "who": "choir", "text": "И слепаго. Подобен: Умныя мои очи, / ослепленныя, Господи, от мрачнаго греха, Ты просвети, / вложив, Щедре, смирение, / и покаяния омый слезами."},
  {"id": "cu-otd-0269", "section": "service", "who": "choir", "text": "На хвалитех поставим стихов 8. И поем стихиры самогласны, слепаго 4, глас 2:"},
  {"id": "cu-otd-0270", "section": "service", "who": "choir", "text": "Слепый родивыйся, в своем помысле глаголаше: / еда аз грех ради родительных родихся без очию, / еда аз за неверие языков родихся во обличение? / Не домышляюся вопрошати, / когда нощь, когда день? / Не терпита ми нозе каменнаго претыкания, / не видех бо солнца сияюща, / ниже во образе мене Создавшаго. / Но молю Ти ся Христе Боже, / призри на мя и помилуй мя."},
  {"id": "cu-otd-0271", "section": "service", "who": "choir", "text": "Мимоходя Иисус от святилища, / обрете человека слепа от рождения, / и умилосердився положи брение на очию его, и рече к нему: / иди умыйся в Силоаме, / и умывся прозре, славу возсылая Богу. / Соседи же его глаголаху ему: / кто твои зеницы отверзе, / ихже никтоже от зрящих исцелити возможе? / Он же возопив, рече: / Человек Иисус глаголемый, / Он ми рече, умыйся в Силоаме, и прозрех. / Той есть воистинну, / Егоже рече Моисей в законе, Христа Мессию: / Той есть Спас душ наших. Глас 4:"},
  {"id": "cu-otd-0272", "section": "service", "who": "choir", "text": "Все житие слепый нощь помышляя, / возопи к Тебе: / Господи, отверзи ми зеницы, / Сыне Давидов Спасе наш, / да со всеми и аз воспою Твою силу. Глас 5:"},
  {"id": "cu-otd-0273", "section": "service", "who": "choir", "text": "Господи, мимоходя путем, / обрел еси человека слепа от рождения, / и удивлени бывше ученицы, вопрошаху Тя глаголюще: / Учителю, кто согреши: сей ли, / или родители его, да слеп родися? / Ты же Спасе мой возопил еси к ним: / ни сей согреши, ни родители его, / но да явятся дела Божия на нем. / Мне подобает делати дела Пославшаго Мя, / яже никтоже может делати. / И сия рек, плюнув долу, и брение сотворь, / помазал еси очи его, рек к нему: / иди, умыйся в Силоамстей купели. / Он же умывся здрав бысть, и вопияше к Тебе: / верую Господи, и поклонися Тебе. / Темже вопием и мы, помилуй нас."},
  {"id": "cu-otd-0274", "section": "service", "who": "choir", "text": "Таже стихиры Пасхи с припевы их. Глас 5: Стих:"},
  {"id": "cu-otd-0275", "section": "service", "who": "choir", "text": "Да воскреснет Бог, / и расточатся врази Его."},
  {"id": "cu-otd-0276", "section": "service", "who": "choir", "text": "Пасха / священная нам днесь показася; / Пасха нова святая; / Пасха таинственная; / Пасха всечестная. / Пасха Христос Избавитель; / Пасха непорочная; / Пасха великая; / Пасха верных. / Пасха двери райския нам отверзающая. / Пасха всех освящающая верных. Стих:"},
  {"id": "cu-otd-0277", "section": "service", "who": "choir", "text": "Яко исчезает дым, / да исчезнут."},
  {"id": "cu-otd-0278", "section": "service", "who": "choir", "text": "Приидите / от видения жены благовестницы, / и Сиону рцыте: / приими / от нас радости благовещения, Воскресения Христова: / красуйся, ликуй / и радуйся, Иерусалиме, / Царя Христа узрев из гроба, / яко жениха происходяща. Стих:"},
  {"id": "cu-otd-0279", "section": "service", "who": "choir", "text": "Тако да погибнут грешницы от Лица Божия, / а праведницы да возвеселятся."},
  {"id": "cu-otd-0280", "section": "service", "who": "choir", "text": "Мироносицы жены, / утру глубоку, / представша гробу Живодавца, / обретоша Ангела / на камени седяща, / и той провещав им, / сице глаголаше: / что ищете Живаго с мертвыми; / что плачете Нетленнаго во тли? / Шедше, проповедите учеником Его. Стих:"},
  {"id": "cu-otd-0281", "section": "service", "who": "choir", "text": "Сей день, егоже сотвори Господь, / возрадуемся и возвеселимся в онь."},
  {"id": "cu-otd-0282", "section": "service", "who": "choir", "text": "Пасха красная, / Пасха, Господня Пасха! / Пасха всечестная / нам возсия. Пасха, / радостию друг друга обымем. / О Пасха! / Избавление скорби, / ибо из гроба днесь, / яко от чертога / возсияв Христос, / жены радости исполни, глаголя: / проповедите апостолом."},
  {"id": "cu-otd-0283", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресения день, / и просветимся торжеством, / и друг друга обымем. / Рцем братие, / и ненавидящим нас, / простим вся Воскресением, / и тако возопиим: / Христос воскресе из мертвых, / смертию смерть поправ, / и сущим во гробех живот даровав. Таже,"},
  {"id": "cu-otd-0284", "section": "service", "who": "choir", "text": "Христос воскресе:"},
  {"id": "cu-otd-0285", "section": "service", "who": "rubric", "text": "якоже указася вечер. И славословие великое."},
  {"id": "cu-otd-0286", "section": "service", "who": "choir", "text": "Тропарь воскресен, глас 5: Собезначальное Слово Отцу и Духови, / от Девы рождшееся на Спасение наше, / воспоим, вернии, и поклонимся; / яко благоволи Плотию взыти на Крест, / и смерть претерпети, / и воскресити умершия / славным воскресением Своим."},
  {"id": "cu-otd-0287", "section": "service", "who": "choir", "text": "Слава, и ныне, Богородичен: Радуйся, Двере Господня непроходимая; / радуйся, стено и покрове притекающим к Тебе. / Радуйся, необуреваемое пристанище и неискусобрачная, / рождшая плотию Творца Твоего и Бога. / Молящи не оскудевай о воспевающих / и кланяющихся рождеству Твоему."},
  {"id": "cu-otd-0288", "section": "service", "who": "rubric", "text": "Ектениа и отпуст без креста. И святаго на отпусте поминает, егоже будет день."},
  {"id": "cu-otd-0289", "section": "service", "who": "rubric", "text": "И час 1, в притворе. На 1-м часе глаголем псалмы обычныя. На"},
  {"id": "cu-otd-0290", "section": "service", "who": "choir", "text": "Слава: тропарь:"},
  {"id": "cu-otd-0291", "section": "service", "who": "choir", "text": "Собезначальное Слово: И ныне: Богородичен:"},
  {"id": "cu-otd-0292", "section": "service", "who": "choir", "text": "Что Тя наречем:"},
  {"id": "cu-otd-0293", "section": "service", "who": "rubric", "text": "По Трисвятом кондак:"},
  {"id": "cu-otd-0294", "section": "service", "who": "choir", "text": "Душевныма очима:"},
  {"id": "cu-otd-0295", "section": "service", "who": "rubric", "text": "И конечный отпуст по обычаю, и прочия часы пред литургиею глаголем трипсалмнии."},
  {"id": "cu-otd-0296", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-otd-0297", "section": "service", "who": "rubric", "text": "Начало литургии, якоже на самую Пасху. На литургии изобразительная, от канона Пасхи, песнь 3-я на 4 (со ирмосом), и песнь 6-я на 4."},
  {"id": "cu-otd-0298", "section": "service", "who": "choir", "text": "По входе тропарь воскресен, глас 5:"},
  {"id": "cu-otd-0299", "section": "service", "who": "choir", "text": "Собезначальное Слово Отцу и Духови, / от Девы рождшееся на Спасение наше, / воспоим, вернии, и поклонимся; / яко благоволи Плотию взыти на Крест, / и смерть претерпети, / и воскресити умершия / славным воскресением Своим."},
  {"id": "cu-otd-0300", "section": "service", "who": "choir", "text": "Слава: кондак слепаго, глас 4:"},
  {"id": "cu-otd-0301", "section": "service", "who": "choir", "text": "Душевныма очима ослеплен, / к Тебе, Христе, прихожду, / якоже слепый от рождения, / покаянием зову Ти: / Ты сущих во тьме Свет пресветлый."},
  {"id": "cu-otd-0302", "section": "service", "who": "choir", "text": "И ныне: кондак Пасхи, глас 8:"},
  {"id": "cu-otd-0303", "section": "service", "who": "choir", "text": "Аще и во гроб снизшел еси, Безсмертне, / но адову разрушил еси силу, / и воскресл еси, яко победитель, Христе Боже, / женам мироносицам вещавый: радуйтеся, / и Твоим апостолом мир даруяй, / падшим подаяй воскресение. И прочая."},
  {"id": "cu-otd-0304", "section": "service", "who": "choir", "text": "Прокимен Пасхи, глас 8: Сей день егоже сотвори Господь, / возрадуемся и возвеселимся вонь. Стих:"},
  {"id": "cu-otd-0305", "section": "service", "who": "choir", "text": "Исповедайтеся Господеви, яко благ, яко в век милость Его."},
  {"id": "cu-otd-0306", "section": "service", "who": "rubric", "text": "Апостол и Евангелие дне."},
  {"id": "cu-otd-0307", "section": "service", "who": "choir", "text": "Апостол в Деяниих, зачало 41. [Деян. 18, 22 – 28]:"},
  {"id": "cu-otd-0308", "section": "service", "who": "choir", "text": "Во дни оны, сшед Павел в Кесарию, возшед и целовав Церковь, сниде во Антиохию. И сотворь время некое, изыде, проходя по ряду Галатийскую страну и Фригию, утверждая вся ученики. Иудеанин же некто, Аполлос именем, Александрянин родом, муж словесен, прииде во Ефес, силен сый в книгах. Сей бе оглашен пути Господню, и горя духом, глаголаше и учаше известно яже о Господе, ведый токмо крещение Иоанново. Сей же начат дерзати на сонмищах. Слышавша же его Акила и Прискилла, прияша его и известнее тому сказаша путь Господень. Хотящу же ему преити во Ахаию, предпославше братия написаша учеником прияти его: иже пришед тамо пособствова много веровавшым благодатию. Твердо бо Иудеи не престая обличаше пред людьми, сказуя Писаньми, Иисуса быти Христа."},
  {"id": "cu-otd-0309", "section": "service", "who": "choir", "text": "Аллилуиа Пасхи, глас 4: Ты воскрес ущедриши Сиона. Стих:"},
  {"id": "cu-otd-0310", "section": "service", "who": "choir", "text": "Господь с Небесе на землю призре."},
  {"id": "cu-otd-0311", "section": "service", "who": "choir", "text": "Евангелие от Иоанна, зачало 43. [Ин. 12, 36 – 47]:"},
  {"id": "cu-otd-0312", "section": "service", "who": "choir", "text": "Рече Господь ко пришедшим к Нему Иудеем: дондеже свет имате, веруйте во свет, да сынове света будете. Сия глагола Иисус, и отшед скрыся от них. Толика знамения сотворшу Ему пред ними, не вероваху в Него. Да сбудется слово Исаии пророка, еже рече: Господи, кто верова слуху нашему, и мышца Господня кому открыся? Сего ради не можаху веровати, яко паки рече Исаиа: ослепи очи их, и окаменил есть сердца их, да не видят очима, ни разумеют сердцем, и обратятся, и исцелю их. Сия рече Исаиа, егда виде славу Его, и глагола о Нем. Обаче убо и от князь мнози вероваша в Него, но фарисей ради не исповедоваху, да не из сонмищ изгнани будут. Возлюбиша бо паче славу человеческую, неже славу Божию. Иисус же воззва, и рече: веруяй в Мя, не верует в Мя, но в пославшаго Мя. И видяй Мя, видит пославшаго Мя. Аз свет в мiр приидох, да всяк веруяй в Мя во тме не пребудет. И аще кто услышит глаголы Моя, и не верует, Аз не сужду ему: не приидох бо, да сужду мiрови, но да спасу мiр."},
  {"id": "cu-otd-0313", "section": "service", "who": "rubric", "text": "И прочая служба воскресна вся."},
  {"id": "cu-otd-0314", "section": "service", "who": "choir", "text": "Причастный: Тело Христово приимите, источника безсмертнаго вкусите, Аллилуиа. трижды."},
  {"id": "cu-otd-0315", "section": "service", "who": "rubric", "text": "Глаголем же и псалом 33:"},
  {"id": "cu-otd-0316", "section": "service", "who": "choir", "text": "Благословлю Господа:"},
  {"id": "cu-otd-0317", "section": "service", "who": "rubric", "text": "Таже иерей творит отпуст Пасхи со крестом, и прочее все поем конец литургии, якоже указася на самую Пасху. И тако отдается праздник святаго и живоноснаго Христова Воскресения."},
];

